// Pega o primeiro item que chega no nó (o dado do webhook)
const item = items[0];

// Acessa o objeto 'body' que contém todas as informações
const body = item.json.body;

// Retorna o próprio objeto 'body' como o novo JSON.
// Isso faz com que todos os campos dentro de 'body' fiquem no nível principal do item.
return [{
  json: body
}];

// NODE N8N: FORMATAR RESPOSTA DO ASSISTANT PARA O SIMULADOR
// Adicione este código em um node "Code" ANTES do "Respond to Webhook"

// Pegar a resposta completa da API OpenAI
const openAIResponse = $input.item.json;

// Verificar se tem dados
if (!openAIResponse || !openAIResponse.data || openAIResponse.data.length === 0) {
  return {
    success: false,
    error: "Nenhuma mensagem encontrada",
    thread_id: $node["Webhook"].json.body.thread_id
  };
}

// Extrair a última mensagem do assistant (primeira no array, pois vem em ordem reversa)
const messages = openAIResponse.data;
const assistantMessage = messages.find(msg => msg.role === 'assistant');

if (!assistantMessage) {
  return {
    success: false,
    error: "Nenhuma resposta do assistant encontrada",
    thread_id: $node["Webhook"].json.body.thread_id
  };
}

// Extrair o texto da mensagem
let responseText = '';
if (assistantMessage.content && assistantMessage.content.length > 0) {
  // Pegar o conteúdo de texto
  const textContent = assistantMessage.content.find(content => content.type === 'text');
  if (textContent && textContent.text) {
    responseText = textContent.text.value;
  }
}

// Detectar a etapa da conversa baseada no conteúdo
let etapa = 'Qualificação';
const textoLower = responseText.toLowerCase();

if (textoLower.includes('agendar') || textoLower.includes('reunião') || textoLower.includes('calendário')) {
  etapa = 'Agendamento';
} else if (textoLower.includes('valor') || textoLower.includes('preço') || textoLower.includes('custo') || textoLower.includes('investimento')) {
  etapa = 'Apresentação de Preço';
} else if (textoLower.includes('obrigado') || textoLower.includes('até breve') || textoLower.includes('falaremos')) {
  etapa = 'Finalização';
} else if (textoLower.includes('diagnóstico') || textoLower.includes('análise')) {
  etapa = 'Proposta';
}

// Pegar dados adicionais do webhook original
const webhookData = $node["Webhook"].json.body;

// Formatar resposta final para o simulador
const response = {
  // Campos obrigatórios
  success: true,
  response: responseText,
  thread_id: assistantMessage.thread_id,

  // Metadados úteis
  etapa: etapa,
  message_id: assistantMessage.id,
  run_id: assistantMessage.run_id,
  assistant_id: assistantMessage.assistant_id,
  created_at: assistantMessage.created_at,

  // Informações do lead
  lead_info: {
    nome: webhookData.user_data?.name,
    empresa: webhookData.user_data?.empresa,
    telefone: webhookData.user_phone
  },

  // Estatísticas
  stats: {
    message_count: messages.length,
    timestamp: new Date().toISOString(),
    processing_time_ms: Date.now() - $node["Webhook"].json.timestamp
  },

  // Debug info (opcional)
  debug: {
    total_messages: messages.length,
    user_message: messages.find(m => m.role === 'user')?.content?.[0]?.text?.value,
    webhook_url: webhookData.source
  }
};

return response;
